    if(active==='comments')return commentsPage(page);
    if(active==='analytics')return analyticsPage(page);
    if(active==='wallet')return walletPage(page);
    if(active==='audience')return audiencePage(page);
    if(active==='notifications')return notificationsPage(page);
    if(active==='playlists')return playlistsPage(page);
    if(active==='premium')return premiumPage(page);
    if(active==='talent')return talentPage(page);
    if(active==='shop')return shopPage(page);
    if(active==='channel')return channelPage(page);
    if(active==='resources')return resourcesPage(page);
    return copyrightPage(page);
