  function resourcesPage(page){page.append(heading('ATHARO GUIDE','তৈরি করো আত্মবিশ্বাসে','প্রকাশের আগে quality checklist, caption standards ও analytics-এর সীমা দেখে নাও.'));const resources=[['01 · প্রকাশের আগে','Title স্পষ্ট ও নির্ভুল রাখো; thumbnail-এ ভিডিওর আসল বিষয় দেখাও; category, subject ও visibility মিলিয়ে নাও।'],['02 · শেখার ভিডিও','Class/level, subject ও syllabus tags যোগ করো। বাংলা/English WebVTT caption এবং timestamp chapters দিলে দর্শক সহজে অনুসরণ করতে পারবে।'],['03 · Community','Comments-এ গঠনমূলকভাবে উত্তর দাও। Pin কেবল গুরুত্বপূর্ণ comment-এ, hide শুধু guideline বা safety-র প্রয়োজনে ব্যবহার করো।'],['04 · Analytics বুঝে নাও','Views unique-view tracking-এর estimate; watch time/retention sampled signal। ছোট sample থেকে বড় সিদ্ধান্ত নিও না।'],['05 · Copyright & safety','অন্যের কাজ ব্যবহারের অধিকার নিশ্চিত করো। Notice ভুল মনে হলে Atharo Studio-তে তথ্য পড়ে appeal দাও; internal strike বাইরের আইনি সিদ্ধান্ত নয়।'],['06 · Creator earnings','আয় campaign CPM/share থেকে আনুমানিক হিসাব। বাস্তব advertiser billing, tax, payout provider বা cash withdrawal এখনো নেই।']];const grid=el('div',{class:'studio-resource-grid'});resources.forEach(([title,body])=>grid.append(el('article',{class:'studio-resource'},[el('strong',{text:title}),el('span',{text:body})])));page.append(panel('Publishing playbook','দ্রুত checklist—সিদ্ধান্ত সবসময় creator-এর।',grid),panel('Atharo Studio shortcuts','',el('div',{class:'console-actions'},[el('a',{href:'/upload',class:'primary-cta',text:'ভিডিও আপলোড ↗'}),el('a',{href:'/channel/me',class:'console-small-button',text:'আমার channel ↗'}),el('a',{href:'/playlists',class:'console-small-button',text:'Playlist দেখো ↗'})])));}
  async function copyrightPage(page){page.append(heading('COPYRIGHT & POLICY','Notices ও appeals','সাইটের internal moderation notice, status ও তোমার appeal একই জায়গায়.'));const data=await loadData('strikes'),items=data.strikes||[],rows=items.map(item=>{const content=el('div',{},[el('strong',{text:item.videoTitle||'ভিডিও আর উপলভ্য নেই'}),el('div',{class:'console-muted',text:'Notice · '+date(item.createdAt)+(item.appealedAt?' · Appealed '+date(item.appealedAt):'')+(item.resolvedAt?' · Reviewed '+date(item.resolvedAt):'')}),el('p',{text:item.reason}),item.evidenceUrl?el('a',{href:item.evidenceUrl,target:'_blank',rel:'noopener noreferrer',class:'console-small-button',text:'Evidence দেখো ↗'}):null,item.appealText?el('div',{class:'console-notice',text:'তোমার appeal: '+item.appealText}):null,item.resolvedByEmail?el('div',{class:'console-muted',text:'Review record · '+item.resolvedByEmail}):null]);if(item.status==='active'){const appeal=el('textarea',{maxlength:'2000',rows:'2',placeholder:'কেন notice review করা উচিত? (কমপক্ষে ১০ অক্ষর)'}),send=btn('Appeal পাঠাও',async()=>{try{await ctx.jsonFetch('/api/creator/strikes/'+encodeURIComponent(item.id)+'/appeal',{method:'POST',body:{appeal:appeal.value}});ctx.notify('Appeal জমা হয়েছে।');cache.strikes=null;await paint();}catch(error){ctx.notify(error.message,'error');}});content.append(appeal,send);}return el('tr',{},[td(content),td(badge(item.status,item.status==='active'?'bad':item.status==='appealed'?'warn':'good'))]);});page.append(panel('Copyright notices','Internal moderation record; এটি আদালত, সরকারি সংস্থা বা বাইরের platform-এর legal decision নয়.',rows.length?table(['Notice ও appeal','অবস্থা'],rows):empty('কোনো copyright notice নেই।')),el('div',{class:'console-notice',text:'Appeal পাঠানোর আগে ভিডিওটি ও notice-এর কারণ পড়ো। Review-এর সময় admin-কে প্রাসঙ্গিক তথ্য দাও; appeal পাঠানো মানেই strike সরবে—এমন নিশ্চয়তা নেই।'}));}
